static_assert(std::is_same_v<format::EncodeTypeFor<format::category::SampleMask>, format::EncodeTypeFor<format::category::UInt32>>);


// A API element carries structure_type exactly when the registry gives the structure one: the row property and
// the API element member are two emissions of that one fact, checked against each other on every row.
#define GFXRECON_INVENTORY_REQUIRE GFXRECON_INVENTORY_HAS_STRUCTURE_TYPE
#define GFXRECON_INVENTORY_VISIT_STRUCT(Name) static_assert(schema::HasStructureType<schema::vulkan::api_elements::Name>);
#define GFXRECON_INVENTORY_VISIT_UNION(Name) GFXRECON_INVENTORY_VISIT_STRUCT(Name)
#include "generated/generated_vulkan_inventory.h"
#define GFXRECON_INVENTORY_FORBID GFXRECON_INVENTORY_HAS_STRUCTURE_TYPE
#define GFXRECON_INVENTORY_VISIT_STRUCT(Name) static_assert(!schema::HasStructureType<schema::vulkan::api_elements::Name>);
#define GFXRECON_INVENTORY_VISIT_UNION(Name) GFXRECON_INVENTORY_VISIT_STRUCT(Name)
#include "generated/generated_vulkan_inventory.h"

// The sizes the generator counted, then the relation checked arithmetically.
constexpr size_t kStructuresCount = util::TypeListSizeV<binding::vulkan::catalog::structures>;
static_assert(kStructuresCount == 1365);
constexpr size_t kUnionsCount = util::TypeListSizeV<binding::vulkan::catalog::unions>;
static_assert(kUnionsCount == 12);
static_assert(util::TypeListSizeV<binding::vulkan::catalog::extensible_structures> == 1144);
static_assert(util::TypeListSizeV<binding::vulkan::catalog::deep_copyable_structures> == 1136);

// Every enumerated type's API element names its table, and every one but a 64-bit flag-bits type is bound to
// its native enum. Nothing is bound to the bare integer types that the 64-bit flag-bits and the Flags
// typedefs are spelled as, which would draw their ToString calls into the enumerant overloads.
static_assert(schema::HasEnumerants<schema::vulkan::api_elements::StdVideoAV1ChromaSamplePosition>);
static_assert(std::is_same_v<binding::ApiElementOf<::StdVideoAV1ChromaSamplePosition>::type, schema::vulkan::api_elements::StdVideoAV1ChromaSamplePosition>);
static_assert(schema::HasEnumerants<schema::vulkan::api_elements::StdVideoAV1ColorPrimaries>);
static_assert(std::is_same_v<binding::ApiElementOf<::StdVideoAV1ColorPrimaries>::type, schema::vulkan::api_elements::StdVideoAV1ColorPrimaries>);
