static_assert(std::is_same_v<binding::ApiElementOf<::StdVideoAV1FrameRestorationType>::type, schema::vulkan::api_elements::StdVideoAV1FrameRestorationType>);
static_assert(schema::HasEnumerants<schema::vulkan::api_elements::StdVideoAV1FrameType>);
